// Package assets holds the images of the program that are compiled into the
// binary.
//
// The files are generated by scripts/genicon; run it after changing the
// drawing to refresh them.
package assets

import _ "embed"

//go:embed icon.ico
var iconICO []byte

// IconICO returns the icon file used by the Windows tray.
func IconICO() []byte { return iconICO }
